// ==========================================================================
// CONFIGURACIÓN DE CUENTOS Y VIDEOS INFANTILES
// ==========================================================================

// 1. CARPETA EXCLUSIVA PARA IMÁGENES INFANTILES:
// Coloca aquí las ilustraciones de tu cuento (ej. 1.png, 2.jpg, 3.jpg...)
const carpetaImagenes = '/media/susej/C06E72656E72545E/Users/PC/Desktop/creador_videos/imagenes_infantiles';

// 2. LISTA DE IMÁGENES (OPCIONAL):
// - Si dejas [] (vacío), tomará TODAS las imágenes de la carpeta en orden numérico/alfabético.
// - O puedes especificar los nombres: ['escena1.jpg', 'escena2.jpg']
const imagenes = [];

// 3. TEXTO DE LA NARRACIÓN DEL CUENTO:
// - OPCIÓN A: Pega aquí la historia infantil o cuento.
// - OPCIÓN B: Déjalo vacío ('') y guarda un archivo 'narracion.txt' en la carpeta de imágenes.
const textoNarracion = `Había una vez un pequeño dragón que le temía al fuego, pero descubrió un secreto mágico que salvó a todo su bosque.`;

// 4. VOZ FEMENINA EN ESPAÑOL LATINOAMERICANO (100% Gratuita, Expresiva y Fluida):
// - 'es-VE-PaolaNeural'   -> Venezuela (Cálida, fluida, humana y expresiva - ¡Recomendada para niños!)
// - 'es-CO-SalomeNeural'  -> Colombia (Dulce, tierna y acogedora para cuentos de dormir)
// - 'es-US-PalomaNeural'  -> Latino Neutro (Moderna y conversacional)
// - 'es-MX-DaliaNeural'   -> México
const voz = 'es-VE-PaolaNeural';

// 5. ESTILO DE SUBTÍTULOS PARA NIÑOS:
// 'infantil' = Letras en Azul Celeste y Morado Mágico con borde oscuro contrastado.
const subtitulos = true;
const estiloSubtitulos = 'infantil';

// 6. TRANSICIONES SUAVES:
// 'dissolve' (desvanecimiento cruzado mágico entre páginas/imágenes) o 'fade'
const transicion = 'dissolve';
const duracionTransicionSegundos = 0.7;

return [{
  json: {
    accion: 'video_infantil',
    carpeta_imagenes: carpetaImagenes,
    imagenes: imagenes,
    texto_narracion: textoNarracion,
    voz: voz,
    transicion: transicion,
    duracion_transicion_segundos: duracionTransicionSegundos,
    subtitulos: subtitulos,
    estilo_subtitulos: estiloSubtitulos
  }
}];

const videoInfo = $('Renderizar Cuento (FFmpeg + Voz Latina + Ken Burns)').first().json;
const aiRaw = $input.first().json.output || $input.first().json.text || '';

let copyData = {};
try {
  const match = aiRaw.match(/\{[\s\S]*\}/);
  copyData = JSON.parse(match ? match[0] : aiRaw);
} catch (e) {
  copyData = {
    titulo_gancho: '✨ UN CUENTO MÁGICO PARA SOÑAR 🌟',
    descripcion: 'Acompaña a nuestros personajes en esta tierna y divertida historia llena de magia y aprendizaje.',
    cta: '¿Cuál fue tu parte favorita del cuento? ¡Dinos en los comentarios y suscríbete para más cuentos!',
    hashtags: ['#cuentosinfantiles', '#historiasparaniños', '#paraniños', '#cuentosparadormir', '#shorts']
  };
}

return [{
  json: {
    status: '🎉 ¡Video infantil generado con éxito!',
    archivo_final: videoInfo.video_final_path || videoInfo.video_path || '/media/susej/C06E72656E72545E/Users/PC/Desktop/creador_videos/videos_listos/video_infantil_final.mp4',
    duracion_segundos: videoInfo.duracion_segundos || 0,
    total_ilustraciones: videoInfo.total_imagenes || 0,
    voz_narradora: videoInfo.voz_utilizada || 'es-MX-DaliaNeural (Femenina Latina Infantil)',
    estilo_subtitulos: 'Azul Celeste y Morado Mágico',
    transicion_utilizada: videoInfo.transicion_utilizada || 'dissolve',
    subtitulos_incluidos: videoInfo.subtitulos_incluidos !== false,
    copy_para_redes: {
      titulo_gancho: copyData.titulo_gancho,
      descripcion: copyData.descripcion,
      cta: copyData.cta,
      hashtags: copyData.hashtags || []
    },
    carpeta_en_tu_pc: 'creador_videos/videos_listos/'
  }
}];
